#include <stdio.h>

/*
    Archivo de prueba para RemoveComments
    Cubre casos de:
    - Comentarios simples y múltiples
    - Cadenas y caracteres
    - Secuencias de escape básicas
*/

// Línea sin comentario
int /*sacame loco*/ main() {
    int a = 0; // contador principal
    int b = 1; /* valor inicial */
    int c = 0; // otro contador
    char c = 'A'; // carácter inicial
    int c = 0; // otro contador
    char d = '\n'; // salto de línea
    char e = '\\'; // barra invertida
    char f = '\''; // comilla simple
    char g = '\"'; // comilla doble

    printf("Hola mundo\n"); // impresión básica
    printf("Esto no es comentario: // ni esto /* comentario */\n");
    printf("Secuencias: \\n \\\\ \\\" \\\'\n");

    // Bloque de código con comentarios intercalados
    a = a + b; /* suma simple */ b = a - b; // resta simple
    /* Comentario
       que ocupa
       varias líneas
    */
    a++; // incremento

    // Casos con casi-comentarios
    printf("/ no es comentario\n");
    printf("* tampoco es comentario\n");
    printf("/x tampoco\n");
    printf("/ "); // barra y espacio antes de fin

    // Comentarios al final de función
    return 0; // fin del main
}

/* Comentario final de archivo */

// A partir de aquí, generamos líneas repetitivas para test de rendimiento
// Se repite un patrón que incluye:
// - Código
// - Comentario de línea
// - Comentario múltiple
// - Cadena con barras y comillas

int dummy_function() {
    int x = 0;
    x++; // comentario de línea
    /* comentario múltiple */
    printf("Cadena con comillas: \"texto\" y barra \\\n");
    printf("/* esto parece comentario pero no lo es */\n");
    printf("// tampoco es comentario\n");
    char ch = '/'; // barra en char
    char ch2 = '*'; // asterisco en char
    char ch3 = '\''; // comilla simple en char
    char ch4 = '\"'; // comilla doble en char
    return x;
}

