    int c = 0; // otro contador
    char c = 'A'; // carácter inicial
    int c = 0; // otro contador
    char d = '\n'; // salto de línea
    char e = '\\'; // barra invertida
    char f = '\''; // comilla simple
    char g = '\"'; // comilla doble

